from fractions import Fraction as Fr
def mul(z,w): return (z[0]*w[0]-z[1]*w[1], z[0]*w[1]+z[1]*w[0])
def coef(n):
    # sum over elements of norm n of (z^4/|z|^4), divided by 4 units; exact rational arithmetic
    re=Fr(0); im=Fr(0); R=int(n**0.5)+1
    for a in range(-R,R+1):
        for b in range(-R,R+1):
            if a*a+b*b==n:
                z2=mul((a,b),(a,b)); z4=mul(z2,z2)
                re+=Fr(z4[0],n*n); im+=Fr(z4[1],n*n)
    return re/4, im/4
assert coef(2)==(-1,0) and coef(5)==(Fr(-14,25),0) and coef(9)==(1,0) and coef(25)==(Fr(-429,625),0)
