def good(n,r):
    col=[-1]*(n+1)
    def bt(i,mx):
        if i>n: return True
        for c in range(min(r,mx+2)):
            if all(not(col[x]==c and col[i-x]==c) for x in range(1,i//2+1)):
                col[i]=c
                if bt(i+1,max(mx,c)): return True
        col[i]=-1
        return False
    return bt(1,-1)
assert good(4,2) and not good(5,2)
assert good(13,3) and not good(14,3)

def free(n,k,r):
    col=[-1]*(n+1)
    def bt(i,mx):
        if i>n: return True
        for c in range(min(r,mx+2)):
            if all(not all(col[i-j*d]==c for j in range(1,k)) for d in range(1,(i-1)//(k-1)+1)):
                col[i]=c
                if bt(i+1,max(mx,c)): return True
        col[i]=-1
        return False
    return bt(1,-1)
