import math
def h(N):
    best=0
    def bt(i,k,D,last):
        nonlocal best
        best=max(best,k)
        for x in range(i,N+1):
            if k+(N-x+1)<=best: return
            nd=0; ok=True
            for s in last:
                b=1<<(x-s)
                if D&b or nd&b: ok=False; break
                nd|=b
            if ok: bt(x+1,k+1,D|nd,last+[x])
    bt(1,0,0,[])
    return best
for N in range(1,35):
    k=h(N)
    assert k <= math.sqrt(N)+N**0.25+1 and k < math.sqrt(2*N)+1

